class BytesIOCopy:
    """A binary stream that copies everything written to it into another
    stream, while itself being backed by a real OS-level temporary file
    (instead of a purely in-memory ``io.BytesIO``).

    Being backed by a real file means the stream supports ``fileno()``,
    so it can be used as the target of APIs that need an actual file
    descriptor, such as ``subprocess.run(..., stdout=stream)``.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3
        Backed by a real temporary file rather than ``io.BytesIO`` so
        that ``fileno()`` is supported.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file: t.BinaryIO = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def close(self) -> None:
        self._file.close()

    @property
    def closed(self) -> bool:
        return self._file.closed

